def _valor_delata_rendicion(valor, marca):
    """UN PROGRAMA, no una IA: la MISMA regla para los campos de codigo y para la lista.

    Julio, 2026-09-30: se saca aqui para no escribirla dos veces. Es rendirse si el valor
    limpio ES la marca, EMPIEZA por la marca, o tiene tres renglones o menos y la marca
    aparece dentro. En cualquier otro caso la marca es contenido.
    """
    limpio = str(valor or "").strip()
    if limpio == marca:
        return True
    if limpio.startswith(marca):
        return True
    if len(limpio.splitlines()) <= 3 and marca in limpio:
        return True
    return False


def _trae_no_encontrado(propuesta, campos):
    """UN PROGRAMA, no una IA: la marca no puede colarse como si fuera contenido.

    Julio, 2026-09-15: nacio porque la marca se colaba como si fuera contenido.
    Julio, 2026-09-30: una ronda entera se perdio porque la marca dentro de un archivo de
    codigo se trataba como rendirse, y el fallo impedia su propia reparacion. Ahora se mira
    DONDE aparece: en el campo de la ruta, cualquier aparicion es rendirse; en los campos de
    codigo, solo si el valor limpio ES la marca, EMPIEZA por la marca, o tiene tres renglones
    o menos y la marca aparece dentro. En cualquier otro caso la marca es contenido.
    Julio, 2026-09-30 (hoy): tambien se mira DENTRO de la lista de cambios, porque por ahi
    paso un trabajo de verdad hoy: un cerebro que se rindio colo su rendicion en un elemento
    de 'cambios' y la comprobacion no la vio.
    """
    marca = "NO" + "_" + "ENCONTRADO"
    for campo in campos:
        valor = str(propuesta.get(campo) or "")
        if campo == "archivo":
            if marca in valor:
                return True
            continue
        if _valor_delata_rendicion(valor, marca):
            return True
    cambios = propuesta.get("cambios")
    if isinstance(cambios, list):
        for elemento in cambios:
            if not isinstance(elemento, dict):
                continue
            if _valor_delata_rendicion(elemento.get("texto_viejo"), marca):
                return True
            if _valor_delata_rendicion(elemento.get("texto_nuevo"), marca):
                return True
    return False

